INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('bolsa-familia','Bolsa Família','Programa de transferência de renda para famílias em situação de pobreza.',(SELECT id FROM public.categories WHERE slug='transferencia-renda'),'Wallet','from-blue-500 to-indigo-600',true,0) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='bolsa-familia'),'O Bolsa Família é um programa federal de transferência direta de renda que beneficia famílias em situação de pobreza e extrema pobreza, garantindo um piso mínimo por pessoa e adicionais para crianças, gestantes e nutrizes.','["Famílias com renda mensal por pessoa de até R$ 218,00","Estar com o CadÚnico atualizado","Manter crianças e adolescentes na escola","Cumprir o calendário de vacinação","Gestantes em acompanhamento pré-natal"]'::jsonb,'["A partir de R$ 600/mês"]'::jsonb,'[{"titulo":"Procure o CRAS","descricao":"Vá ao Centro de Referência de Assistência Social mais próximo da sua casa."},{"titulo":"Faça o CadÚnico","descricao":"Cadastre todos os membros da família no Cadastro Único."},{"titulo":"Aguarde a seleção","descricao":"O governo avalia automaticamente as famílias dentro do perfil."},{"titulo":"Receba pela Caixa","descricao":"Use o cartão do programa, app Caixa Tem ou lotéricas para sacar."}]'::jsonb,'["CPF do responsável familiar","Documento de identidade com foto","Certidão de nascimento de crianças e adolescentes","Comprovante de residência atualizado","Carteira de vacinação das crianças","Comprovante de matrícula escolar"]'::jsonb,'{"dicas":["Guarde sempre o número do NIS","Acompanhe pelo app Caixa Tem","Avise o CRAS sobre mudanças na família"],"errosComuns":[{"titulo":"CadÚnico desatualizado","descricao":"O cadastro deve ser revisto a cada 24 meses ou após qualquer mudança."},{"titulo":"Dados incorretos","descricao":"Renda, endereço ou composição familiar errados podem bloquear o benefício."},{"titulo":"Não cumprir as regras","descricao":"Faltas escolares ou vacinas atrasadas suspendem o pagamento."}],"faq":[{"pergunta":"Posso acumular com outros benefícios?","resposta":"Sim. BPC, Auxílio Gás e Tarifa Social podem ser acumulados respeitando as regras de cada um."},{"pergunta":"Quanto tempo até começar a receber?","resposta":"De 30 a 90 dias após o CadÚnico completo."},{"pergunta":"O benefício pode ser cortado?","resposta":"Sim, se a família descumprir condicionalidades ou a renda mudar."}]}'::jsonb,false) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('bpc-loas','Benefício de Prestação Continuada (BPC)','1 salário mínimo por mês para idosos e pessoas com deficiência de baixa renda.',(SELECT id FROM public.categories WHERE slug='transferencia-renda'),'Wallet','from-blue-500 to-indigo-600',true,1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='bpc-loas'),'O BPC, previsto na LOAS, garante 1 salário mínimo mensal a idosos com 65 anos ou mais e a pessoas com deficiência de qualquer idade, desde que comprovem não possuir meios de prover a própria manutenção nem tê-la provida pela família.','["Idosos com 65 anos ou mais","Pessoas com deficiência de qualquer idade","Renda por pessoa da família de até 1/4 do salário mínimo","Estar inscrito no CadÚnico","Brasileiros ou estrangeiros naturalizados residentes no Brasil"]'::jsonb,'["1 salário mínimo/mês"]'::jsonb,'[{"titulo":"Atualize o CadÚnico","descricao":"Vá ao CRAS e mantenha os dados da família em dia."},{"titulo":"Solicite pelo Meu INSS","descricao":"Use o app/site Meu INSS ou ligue 135 para pedir o benefício."},{"titulo":"Faça a perícia (PcD)","descricao":"A pessoa com deficiência passa por avaliação social e médica."},{"titulo":"Acompanhe a análise","descricao":"Resposta sai no Meu INSS; aprovado começa a receber pelo banco."}]'::jsonb,'["CPF e documento de identidade","CadÚnico atualizado","Comprovante de residência","Laudo médico (no caso de PcD)","Documentos da família que mora junto"]'::jsonb,'{"dicas":["Guarde o número do protocolo do INSS","Solicite a revisão se a renda da família mudar","Mantenha laudos médicos sempre atualizados"],"errosComuns":[{"titulo":"Confundir com aposentadoria","descricao":"BPC não é aposentadoria e não dá 13º nem deixa pensão."},{"titulo":"Esquecer de atualizar o CadÚnico","descricao":"Sem atualização a cada 2 anos, o benefício pode ser bloqueado."},{"titulo":"Não comparecer à perícia","descricao":"Faltar à perícia médica do INSS arquiva o pedido."}],"faq":[{"pergunta":"Posso trabalhar recebendo BPC?","resposta":"Pessoas com deficiência podem trabalhar como aprendiz por até 2 anos sem perder o benefício."},{"pergunta":"Tem 13º salário?","resposta":"Não. O BPC é benefício assistencial e não tem 13º."},{"pergunta":"Posso acumular com Bolsa Família?","resposta":"Em regra não, mas pode acumular com Auxílio Gás e Tarifa Social."}]}'::jsonb,false) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('auxilio-gas','Auxílio Gás dos Brasileiros','Ajuda no valor de um botijão de gás de 13kg para famílias de baixa renda.',(SELECT id FROM public.categories WHERE slug='transferencia-renda'),'Wallet','from-blue-500 to-indigo-600',true,2) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='auxilio-gas'),'O Auxílio Gás dos Brasileiros é um benefício que paga, a cada dois meses, o equivalente ao valor médio nacional de um botijão de gás de cozinha de 13kg, ajudando famílias de baixa renda a manterem o fogão aceso.','["Famílias inscritas no CadÚnico","Renda por pessoa de até meio salário mínimo","Famílias com membros recebendo BPC","Preferência para mulheres responsáveis pelo lar"]'::jsonb,'["100% do valor do botijão"]'::jsonb,'[{"titulo":"Atualize o CadÚnico","descricao":"Procure o CRAS e mantenha o cadastro em dia."},{"titulo":"Aguarde a seleção automática","descricao":"Não há inscrição direta: o governo seleciona famílias do CadÚnico."},{"titulo":"Consulte pelo Caixa Tem","descricao":"Verifique se foi contemplado pelo app Caixa Tem ou no 111."},{"titulo":"Saque pelo Caixa Tem","descricao":"Use o cartão Bolsa Família, Caixa Tem ou lotéricas para sacar."}]'::jsonb,'["CPF do responsável familiar","CadÚnico atualizado nos últimos 24 meses","Documento de identidade","Comprovante de residência"]'::jsonb,'{"dicas":["Pagamento ocorre a cada 2 meses","Consulte a data no calendário da Caixa","Acumula com Bolsa Família e Tarifa Social"],"errosComuns":[{"titulo":"Pensar que precisa comprar gás antes","descricao":"O dinheiro cai independentemente da compra do botijão."},{"titulo":"Cadastro desatualizado","descricao":"Sem CadÚnico atualizado a família sai da lista."},{"titulo":"Mudança de responsável familiar","descricao":"Trocas devem ser informadas no CRAS para não cortar."}],"faq":[{"pergunta":"Recebo todo mês?","resposta":"Não. O pagamento é bimestral."},{"pergunta":"Preciso comprovar a compra do gás?","resposta":"Não, o valor é livre."},{"pergunta":"Quem já recebe Bolsa Família tem prioridade?","resposta":"Sim, esse público é o foco principal do programa."}]}'::jsonb,false) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('auxilio-inclusao','Auxílio-Inclusão','Meio salário mínimo para pessoas com deficiência que voltam ao mercado de trabalho.',(SELECT id FROM public.categories WHERE slug='transferencia-renda'),'Wallet','from-blue-500 to-indigo-600',true,3) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='auxilio-inclusao'),'O Auxílio-Inclusão é pago à pessoa com deficiência que recebia ou tem direito ao BPC e passou a trabalhar com carteira assinada, recebendo até 2 salários mínimos. O objetivo é estimular a inclusão no mercado de trabalho sem perder a proteção social.','["Pessoas com deficiência moderada ou grave","Estar recebendo ou ter direito ao BPC nos últimos 5 anos","Ter atividade remunerada com remuneração até 2 salários mínimos","Estar inscrito no CadÚnico e CPF regular"]'::jsonb,'["50% do salário mínimo"]'::jsonb,'[{"titulo":"Acesse o Meu INSS","descricao":"Faça login no app ou site Meu INSS."},{"titulo":"Solicite ''Auxílio-Inclusão''","descricao":"Selecione o serviço e preencha os dados."},{"titulo":"Anexe documentos","descricao":"Envie comprovantes de vínculo e renda."},{"titulo":"Acompanhe","descricao":"Resposta sai pelo Meu INSS ou pelo 135."}]'::jsonb,'["CPF e identidade","Carteira de trabalho ou contrato","CadÚnico atualizado","Documentos da deficiência (BPC ativo ou recente)"]'::jsonb,'{"dicas":["Mantenha o BPC suspenso (e não cessado) para facilitar a volta","Comunique mudanças de emprego ao INSS","Guarde sempre o protocolo do pedido"],"errosComuns":[{"titulo":"Achar que perde o BPC para sempre","descricao":"O BPC pode ser retomado se a pessoa deixar o trabalho."},{"titulo":"Ganhar acima do limite","descricao":"Renda acima de 2 salários mínimos encerra o auxílio."},{"titulo":"Cadúnico vencido","descricao":"Bloqueia o pedido automaticamente."}],"faq":[{"pergunta":"Posso voltar ao BPC?","resposta":"Sim, quando o trabalho terminar você pode pedir a retomada."},{"pergunta":"Tem 13º?","resposta":"Não, é benefício assistencial."},{"pergunta":"Acumula com Bolsa Família?","resposta":"Não acumula com BPC ativo, mas pode acumular com outros."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('pe-de-meia','Programa Pé-de-Meia','Poupança para estudantes do Ensino Médio público de baixa renda.',(SELECT id FROM public.categories WHERE slug='transferencia-renda'),'Wallet','from-blue-500 to-indigo-600',true,4) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='pe-de-meia'),'O Pé-de-Meia é uma poupança de incentivo à permanência e conclusão escolar para estudantes de 14 a 24 anos matriculados no Ensino Médio público, inscritos no CadÚnico e em famílias de baixa renda.','["Estudantes de 14 a 24 anos no Ensino Médio público","Famílias inscritas no CadÚnico","Renda por pessoa até meio salário mínimo","Frequência mínima de 80% nas aulas","Aprovação no ano letivo"]'::jsonb,'["Até R$ 9.200 ao longo do Ensino Médio"]'::jsonb,'[{"titulo":"Confirme a matrícula","descricao":"A escola informa o MEC sobre quem está matriculado."},{"titulo":"Mantenha o CadÚnico em dia","descricao":"Atualize seus dados no CRAS."},{"titulo":"Acompanhe pelo app Jornada do Estudante","descricao":"Veja parcelas, frequência e pagamentos."},{"titulo":"Receba pela Caixa","descricao":"Pagamentos caem em conta poupança da Caixa Econômica."}]'::jsonb,'["CPF do estudante","Documento de identidade","Matrícula em escola pública de Ensino Médio","CadÚnico atualizado"]'::jsonb,'{"dicas":["Parcelas mensais + bônus anual por aprovação","Bônus de R$ 200 por participar do Enem","Saque do valor final só após conclusão do Ensino Médio"],"errosComuns":[{"titulo":"Não ter CPF próprio","descricao":"Sem CPF ativo o cadastro não é aceito."},{"titulo":"Faltar à escola","descricao":"Frequência abaixo de 80% suspende a parcela."},{"titulo":"Esquecer de baixar o app","descricao":"Sem o app você não acompanha o pagamento."}],"faq":[{"pergunta":"Qual o valor total?","resposta":"Pode chegar a cerca de R$ 9.200 ao longo do Ensino Médio."},{"pergunta":"Posso sacar todo mês?","resposta":"Parte é mensal, parte fica retida e é liberada ao concluir o Ensino Médio."},{"pergunta":"Estudo à noite, posso participar?","resposta":"Sim, EJA e Ensino Médio noturno também entram."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('isencao-enem','Isenção da Taxa do Enem','Não pague a inscrição do Enem se você é estudante de baixa renda.',(SELECT id FROM public.categories WHERE slug='educacao'),'GraduationCap','from-violet-500 to-purple-600',true,5) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='isencao-enem'),'A isenção da taxa do Enem garante inscrição gratuita no Exame Nacional do Ensino Médio para estudantes da rede pública e de baixa renda, ampliando o acesso à educação superior.','["Estudantes concluindo o Ensino Médio em escola pública no ano do exame","Famílias com renda por pessoa de até 1,5 salário mínimo","Pessoas em situação de vulnerabilidade inscritas no CadÚnico","Quem teve a isenção e não compareceu pode justificar a ausência"]'::jsonb,'["100% da taxa de inscrição"]'::jsonb,'[{"titulo":"Acompanhe o edital do Inep","descricao":"A janela de isenção abre antes do período normal de inscrição."},{"titulo":"Cadastre-se na Página do Participante","descricao":"Acesse enem.inep.gov.br e crie sua conta."},{"titulo":"Solicite a isenção","descricao":"Marque o motivo (escola pública, CadÚnico, etc.)."},{"titulo":"Confirme a inscrição no Enem","descricao":"Mesmo com isenção, é preciso confirmar a inscrição na data normal."}]'::jsonb,'["CPF","Comprovante de matrícula em escola pública","NIS do CadÚnico (quando aplicável)","Comprovante de renda da família"]'::jsonb,'{"dicas":["Faça as duas etapas: isenção e inscrição","Justifique a falta no prazo se não puder ir","Use o app ''Enem'' para acompanhar"],"errosComuns":[{"titulo":"Não confirmar a inscrição","descricao":"Conseguir a isenção não inscreve automaticamente."},{"titulo":"Faltar sem justificar","descricao":"Quem usa isenção e falta perde o direito no ano seguinte."},{"titulo":"Esquecer o NIS","descricao":"Inscritos no CadÚnico precisam informar o NIS corretamente."}],"faq":[{"pergunta":"Quem teve a isenção e faltou pode pedir de novo?","resposta":"Sim, mas precisa justificar a ausência no sistema do Inep."},{"pergunta":"Vale só para um ano?","resposta":"Sim, a isenção é por edição do Enem."},{"pergunta":"Posso me inscrever sem isenção depois?","resposta":"Pode, pagando a taxa normalmente."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('isencao-concursos','Isenção em Concursos Públicos','Inscrição gratuita em concursos para inscritos no CadÚnico.',(SELECT id FROM public.categories WHERE slug='educacao'),'GraduationCap','from-violet-500 to-purple-600',true,6) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='isencao-concursos'),'Pessoas inscritas no CadÚnico e de baixa renda têm direito à isenção de taxa em concursos públicos federais (e em muitos estaduais e municipais), conforme Decreto nº 6.593/2008.','["Pessoas inscritas no CadÚnico","Renda por pessoa de até meio salário mínimo","Doadores de medula óssea (em muitos editais)","Pessoas com deficiência conforme cada edital"]'::jsonb,'["100% da taxa de inscrição"]'::jsonb,'[{"titulo":"Leia o edital","descricao":"Veja se o concurso oferece isenção e o prazo específico."},{"titulo":"Solicite no site da banca","descricao":"Marque a opção de isenção e informe o NIS."},{"titulo":"Acompanhe o resultado","descricao":"A banca consulta o CadÚnico e divulga lista de isentos."},{"titulo":"Confirme a inscrição","descricao":"Mesmo isento, é preciso finalizar a inscrição."}]'::jsonb,'["CPF","Número do NIS","Documento de identidade","Comprovantes exigidos no edital específico"]'::jsonb,'{"dicas":["Verifique o NIS no app CadÚnico","Solicite a isenção logo no primeiro dia do prazo","Guarde o comprovante de isenção"],"errosComuns":[{"titulo":"NIS inativo","descricao":"Se o NIS não consta no CadÚnico atualizado, o pedido é negado."},{"titulo":"Perder o prazo de isenção","descricao":"O prazo costuma ser bem curto, antes do prazo geral."},{"titulo":"Não confirmar inscrição","descricao":"Isenção concedida ≠ inscrição confirmada."}],"faq":[{"pergunta":"Vale para todos os concursos?","resposta":"Para federais, sim. Estaduais e municipais seguem leis próprias."},{"pergunta":"Posso pedir várias isenções?","resposta":"Sim, uma por concurso."},{"pergunta":"Se for negada posso recorrer?","resposta":"Geralmente sim, o edital define o prazo de recurso."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('sisu-cotas','Sistema de Cotas e SISU','Vagas reservadas em universidades públicas para estudantes de escola pública, pretos, pardos, indígenas e PcD.',(SELECT id FROM public.categories WHERE slug='educacao'),'GraduationCap','from-violet-500 to-purple-600',true,7) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='sisu-cotas'),'O SISU (Sistema de Seleção Unificada) usa a nota do Enem para distribuir vagas em universidades federais. A Lei de Cotas reserva no mínimo 50% das vagas para egressos de escola pública, com subcotas para baixa renda, pretos, pardos, indígenas e PcD.','["Ter feito o Enem no ano anterior, sem zerar a redação","Para cotas: ter cursado todo o Ensino Médio em escola pública","Subcotas conforme renda, raça e deficiência","Atender requisitos específicos de cada universidade"]'::jsonb,'["Vaga em universidade federal"]'::jsonb,'[{"titulo":"Faça o Enem","descricao":"Inscreva-se e realize o exame."},{"titulo":"Inscreva-se no SISU","descricao":"Use sua nota no site sisu.mec.gov.br nas datas oficiais."},{"titulo":"Escolha cursos e modalidade","descricao":"Marque ampla concorrência ou cota correspondente."},{"titulo":"Faça a matrícula","descricao":"Apresente os documentos na universidade dentro do prazo."}]'::jsonb,'["Comprovante de Ensino Médio em escola pública","Documentos de comprovação de renda","Autodeclaração étnico-racial (quando aplicável)","Laudo médico (para cotas PcD)"]'::jsonb,'{"dicas":["Confira documentos de cota com antecedência","Acompanhe a lista de espera","Verifique editais complementares da universidade"],"errosComuns":[{"titulo":"Marcar cota errada","descricao":"Escolher subcota incompatível com a renda/raça reprova na matrícula."},{"titulo":"Perder a chamada","descricao":"Sem matrícula no prazo a vaga é perdida."},{"titulo":"Não acompanhar a lista de espera","descricao":"Muitas vagas saem só nas chamadas seguintes."}],"faq":[{"pergunta":"Estudei parte em escola particular, posso usar cota?","resposta":"Não. A regra é Ensino Médio integralmente em escola pública."},{"pergunta":"Posso mudar cota depois?","resposta":"Não, só dentro do prazo do edital do SISU."},{"pergunta":"Cota PcD precisa de laudo?","resposta":"Sim, com CID e assinatura médica."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('pnaes','Programa Nacional de Assistência Estudantil (PNAES)','Auxílios de moradia, alimentação e transporte para estudantes de universidades federais.',(SELECT id FROM public.categories WHERE slug='educacao'),'GraduationCap','from-violet-500 to-purple-600',true,8) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='pnaes'),'O PNAES apoia a permanência de estudantes de graduação em universidades e institutos federais com auxílios financeiros, moradia estudantil, alimentação no RU, transporte, creche e apoio pedagógico.','["Estudantes regularmente matriculados em IFES","Renda familiar por pessoa de até 1,5 salário mínimo","Prioridade para estudantes vindos de escola pública","Critérios complementares de cada instituição"]'::jsonb,'["Variável por universidade"]'::jsonb,'[{"titulo":"Procure a Pró-Reitoria de Assistência","descricao":"Cada IFES tem o setor responsável pelo PNAES."},{"titulo":"Acompanhe os editais","descricao":"Inscrições abrem em períodos definidos no calendário."},{"titulo":"Faça a inscrição online","descricao":"Envie documentos pelo sistema da universidade."},{"titulo":"Passe pela avaliação social","descricao":"Assistente social analisa a situação familiar."}]'::jsonb,'["Comprovantes de renda de todos da família","Comprovante de residência","Histórico escolar","Documentos de identidade e CPF"]'::jsonb,'{"dicas":["Junte documentos antes do edital abrir","Acompanhe o e-mail acadêmico","Procure o serviço social em caso de dúvida"],"errosComuns":[{"titulo":"Perder o edital","descricao":"Cada auxílio tem prazo específico e curto."},{"titulo":"Documentação incompleta","descricao":"Faltar 1 documento elimina o pedido."},{"titulo":"Não renovar","descricao":"Muitos auxílios precisam ser renovados a cada semestre/ano."}],"faq":[{"pergunta":"Posso acumular auxílios?","resposta":"Sim, em geral pode combinar moradia + alimentação + transporte."},{"pergunta":"Vale para pós-graduação?","resposta":"O foco é a graduação; pós tem programas específicos."},{"pergunta":"Posso perder o auxílio?","resposta":"Sim, se mudar a renda ou trancar a matrícula."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('fies-social','FIES Social','Financiamento estudantil com até 100% do curso para inscritos no CadÚnico.',(SELECT id FROM public.categories WHERE slug='educacao'),'GraduationCap','from-violet-500 to-purple-600',true,9) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='fies-social'),'O FIES Social é uma modalidade do Fundo de Financiamento Estudantil que prioriza candidatos de famílias inscritas no CadÚnico, podendo financiar 100% das mensalidades do curso superior em instituições privadas.','["Inscrição no CadÚnico","Renda por pessoa de até meio salário mínimo","Mínimo de 450 pontos no Enem e nota acima de zero na redação","Não ter concluído ensino superior"]'::jsonb,'["Até 100% do financiamento"]'::jsonb,'[{"titulo":"Inscreva-se no FIES","descricao":"Acesse acessounico.fies.mec.gov.br e crie sua conta."},{"titulo":"Escolha curso e instituição","descricao":"Faça a opção dentro dos cursos elegíveis ao FIES Social."},{"titulo":"Aguarde a chamada","descricao":"MEC convoca dentro das vagas disponíveis."},{"titulo":"Conclua na faculdade e banco","descricao":"Valide documentos na instituição e formalize o contrato."}]'::jsonb,'["CPF e identidade","Comprovantes de renda da família","Comprovante de inscrição no CadÚnico","Boletim do Enem"]'::jsonb,'{"dicas":["Confirme o CadÚnico antes de se inscrever","Confira a nota mínima exigida","Leia o contrato com calma antes de assinar"],"errosComuns":[{"titulo":"CadÚnico desatualizado","descricao":"Sai automaticamente da lista do FIES Social."},{"titulo":"Curso não elegível","descricao":"Nem todo curso aceita FIES; conferir lista oficial."},{"titulo":"Atrasar a contratação no banco","descricao":"Perde a vaga e precisa esperar próximo edital."}],"faq":[{"pergunta":"Preciso pagar durante o curso?","resposta":"Não, o pagamento começa após a formatura, com carência."},{"pergunta":"Posso quitar antecipado?","resposta":"Sim, com descontos previstos em lei."},{"pergunta":"Tem fiador?","resposta":"FIES Social dispensa fiador para a maioria dos casos."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('dignidade-menstrual','Programa Dignidade Menstrual','Absorventes gratuitos para pessoas que menstruam em situação de vulnerabilidade.',(SELECT id FROM public.categories WHERE slug='educacao'),'GraduationCap','from-violet-500 to-purple-600',true,10) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='dignidade-menstrual'),'O Programa Dignidade Menstrual garante distribuição gratuita de absorventes higiênicos para estudantes da rede pública, pessoas em situação de rua, presídios femininos e mulheres em vulnerabilidade social inscritas no CadÚnico.','["Estudantes da rede pública em situação de vulnerabilidade","Mulheres em situação de rua","Mulheres privadas de liberdade","Pessoas inscritas no CadÚnico com renda baixa"]'::jsonb,'["Absorventes gratuitos"]'::jsonb,'[{"titulo":"Cadastre-se pelo app Meu SUS Digital","descricao":"Faça login e confirme o direito ao programa."},{"titulo":"Gere a autorização","descricao":"O app emite um código para retirada em farmácia credenciada."},{"titulo":"Retire em farmácia da rede","descricao":"Apresente CPF e o código nas farmácias parceiras."},{"titulo":"Repita a cada ciclo","descricao":"É possível retirar nova cota mensalmente."}]'::jsonb,'["CPF","Comprovante de matrícula (estudantes)","Inscrição no CadÚnico atualizada","Documento de identidade"]'::jsonb,'{"dicas":["Consulte farmácias credenciadas no app","Guarde a autorização no celular","Atualize sempre o CadÚnico no CRAS"],"errosComuns":[{"titulo":"Não atualizar dados","descricao":"Sem CadÚnico atualizado o pedido é negado."},{"titulo":"Esquecer o código","descricao":"Sem o código a farmácia não entrega."},{"titulo":"Procurar farmácia fora da rede","descricao":"Só farmácias credenciadas entregam o produto."}],"faq":[{"pergunta":"Tem custo para a pessoa?","resposta":"Não. Os absorventes são totalmente gratuitos."},{"pergunta":"Quantos pacotes por mês?","resposta":"A quantidade segue a tabela do programa, em geral 1 pacote/mês."},{"pergunta":"Pessoas trans têm direito?","resposta":"Sim, qualquer pessoa que menstrue e atenda aos critérios sociais."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('pnae','Programa Nacional de Alimentação Escolar (PNAE)','Refeições gratuitas nas escolas públicas de educação básica.',(SELECT id FROM public.categories WHERE slug='educacao'),'GraduationCap','from-violet-500 to-purple-600',true,11) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='pnae'),'O PNAE garante alimentação escolar e ações de educação alimentar a todos os alunos da educação básica matriculados em escolas públicas, filantrópicas e comunitárias conveniadas.','["Estudantes da educação básica em escolas públicas","Educação infantil, fundamental, médio e EJA","Estudantes de escolas filantrópicas conveniadas","Estudantes indígenas e quilombolas (cardápio diferenciado)"]'::jsonb,'["Alimentação escolar gratuita"]'::jsonb,'[{"titulo":"Matricule na escola pública","descricao":"A matrícula já garante o direito."},{"titulo":"Acompanhe o cardápio","descricao":"Cada escola publica o cardápio elaborado por nutricionista."},{"titulo":"Participe do Conselho de Alimentação Escolar","descricao":"Pais e mães podem fiscalizar a qualidade."},{"titulo":"Denuncie problemas","descricao":"Em caso de falta ou má qualidade, acione o CAE municipal."}]'::jsonb,'["Matrícula ativa em escola pública","Documento da criança (RG ou certidão)","Carteira de vacinação"]'::jsonb,'{"dicas":["30% dos alimentos devem vir da agricultura familiar","Há cardápios específicos para alergias","Procure o CAE para fiscalizar"],"errosComuns":[{"titulo":"Achar que precisa pagar taxa","descricao":"É 100% gratuito."},{"titulo":"Não informar restrição alimentar","descricao":"A escola precisa saber para adaptar o cardápio."},{"titulo":"Não acompanhar o CAE","descricao":"O controle social é o que melhora a alimentação."}],"faq":[{"pergunta":"Vale para creche?","resposta":"Sim, inclui educação infantil."},{"pergunta":"Alunos com alergia são contemplados?","resposta":"Sim, mediante laudo médico apresentado à escola."},{"pergunta":"Tem alimentação no EJA noturno?","resposta":"Sim, em geral é servido jantar."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('tarifa-social-energia','Tarifa Social de Energia Elétrica','Descontos de até 65% na conta de luz para famílias de baixa renda.',(SELECT id FROM public.categories WHERE slug='energia-agua-comunicacao'),'Zap','from-amber-500 to-orange-600',true,12) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='tarifa-social-energia'),'A Tarifa Social de Energia Elétrica concede descontos progressivos na conta de luz para famílias inscritas no CadÚnico com renda baixa ou que recebem BPC, podendo zerar a conta em alguns casos para consumo de até 30 kWh.','["Famílias inscritas no CadÚnico com renda por pessoa até meio salário mínimo","Famílias que recebem BPC","Famílias com pessoa com doença que precise de equipamento elétrico","Indígenas e quilombolas inscritos no CadÚnico"]'::jsonb,'["Até 65% de desconto"]'::jsonb,'[{"titulo":"Atualize o CadÚnico","descricao":"Mantenha os dados no CRAS em dia."},{"titulo":"Aguarde inscrição automática","descricao":"A maioria entra automaticamente via cruzamento de dados."},{"titulo":"Procure a distribuidora","descricao":"Se não entrou, vá à distribuidora com CPF, NIS e conta de luz."},{"titulo":"Confirme o desconto","descricao":"O desconto aparece na fatura seguinte."}]'::jsonb,'["CPF do titular da conta","Número do NIS","Conta de luz atual","Laudos médicos (se for o caso)"]'::jsonb,'{"dicas":["Verifique se a conta veio com desconto","Use lâmpadas de LED para gastar menos","Acompanhe o consumo mês a mês"],"errosComuns":[{"titulo":"Conta em nome de outra pessoa","descricao":"Precisa estar em nome de alguém da família inscrita."},{"titulo":"CadÚnico vencido","descricao":"Sem atualização o desconto é cortado."},{"titulo":"Mudar de endereço sem avisar","descricao":"Precisa pedir a Tarifa Social no novo endereço."}],"faq":[{"pergunta":"Tem limite de consumo?","resposta":"Os descontos diminuem conforme o consumo sobe; acima de 220 kWh não há desconto."},{"pergunta":"Posso acumular com outros benefícios?","resposta":"Sim, com Bolsa Família, BPC e Auxílio Gás."},{"pergunta":"Vale para condomínio?","resposta":"Não, é por unidade consumidora individual."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('tarifa-social-agua','Tarifa Social de Água e Esgoto','Desconto na conta de água para famílias inscritas no CadÚnico.',(SELECT id FROM public.categories WHERE slug='energia-agua-comunicacao'),'Zap','from-amber-500 to-orange-600',true,13) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='tarifa-social-agua'),'A Tarifa Social de Água e Esgoto é oferecida pelas companhias de saneamento e concede descontos significativos na conta para famílias de baixa renda. As regras variam por estado e município.','["Famílias inscritas no CadÚnico","Renda por pessoa de até meio salário mínimo (regra varia)","Beneficiários do BPC","Critérios complementares da concessionária local"]'::jsonb,'["Variável por estado"]'::jsonb,'[{"titulo":"Confirme regras locais","descricao":"Verifique no site da companhia de saneamento."},{"titulo":"Reúna a documentação","descricao":"Junte CPF, NIS e conta de água."},{"titulo":"Cadastre-se na companhia","descricao":"Vá a uma agência ou solicite pelo site/app."},{"titulo":"Aguarde análise","descricao":"O desconto entra na fatura seguinte se aprovado."}]'::jsonb,'["CPF e identidade","NIS / CadÚnico atualizado","Conta de água em nome de pessoa da família","Comprovante de residência"]'::jsonb,'{"dicas":["Cuide do consumo: grandes vazamentos elevam a conta mesmo com desconto","Tire dúvidas no 0800 da concessionária","Procure o CRAS se precisar ajuda no cadastro"],"errosComuns":[{"titulo":"Conta no nome errado","descricao":"Deve estar em nome de um membro da família cadastrada."},{"titulo":"Não renovar quando exigido","descricao":"Algumas companhias pedem renovação anual."},{"titulo":"Esquecer de avisar mudança","descricao":"Mudou de endereço? Solicite de novo."}],"faq":[{"pergunta":"Vale para todo o Brasil?","resposta":"Quase todas as capitais oferecem, mas regras variam."},{"pergunta":"Acumula com Tarifa Social de Energia?","resposta":"Sim, são programas independentes."},{"pergunta":"Se eu sair do CadÚnico perco?","resposta":"Sim, o desconto cai junto."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('digitaliza-brasil','Programa Digitaliza Brasil (TV Digital)','Kit de TV digital gratuito para famílias do CadÚnico.',(SELECT id FROM public.categories WHERE slug='energia-agua-comunicacao'),'Zap','from-amber-500 to-orange-600',true,14) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='digitaliza-brasil'),'O Digitaliza Brasil substitui a antiga ''caixinha'' digital, oferecendo gratuitamente kits de TV digital (antena + conversor) para famílias inscritas no CadÚnico em áreas onde houve desligamento do sinal analógico ou onde há expansão da TV digital aberta.','["Famílias inscritas no CadÚnico","Renda por pessoa de até meio salário mínimo","Residir em região coberta pelo programa","Não ter recebido o kit anteriormente"]'::jsonb,'["Kit gratuito"]'::jsonb,'[{"titulo":"Confirme a cobertura","descricao":"Verifique no site oficial se sua região está contemplada."},{"titulo":"Ligue 147 ou acesse o site","descricao":"Solicite o agendamento da entrega/instalação."},{"titulo":"Receba em casa","descricao":"Equipe credenciada entrega antena e conversor."},{"titulo":"Instale e sintonize","descricao":"Siga o manual ou peça ajuda à equipe na entrega."}]'::jsonb,'["CPF do responsável","NIS / CadÚnico atualizado","Comprovante de residência","Documento de identidade"]'::jsonb,'{"dicas":["Nunca pague por instalação","Anote o número de protocolo do pedido","Veja a cobertura no site sejadigital.com.br"],"errosComuns":[{"titulo":"Acreditar em golpes","descricao":"O kit é gratuito, nunca pague nada."},{"titulo":"Dados desatualizados","descricao":"CadÚnico vencido cancela a entrega."},{"titulo":"Recusar o agendamento","descricao":"Se não receber em duas tentativas, perde a vaga."}],"faq":[{"pergunta":"Funciona em qualquer TV?","resposta":"Sim, mesmo TVs antigas com conversor."},{"pergunta":"Inclui antena parabólica?","resposta":"Não, isso é o Programa Parabólica Digital."},{"pergunta":"Tem mensalidade?","resposta":"Não, é totalmente gratuito."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('parabolica-digital','Programa Parabólica Digital','Troca gratuita da antena parabólica antiga pela digital.',(SELECT id FROM public.categories WHERE slug='energia-agua-comunicacao'),'Zap','from-amber-500 to-orange-600',true,15) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='parabolica-digital'),'O Programa Parabólica Digital substitui gratuitamente, para famílias inscritas no CadÚnico, a antena parabólica antiga (banda C) por uma nova antena digital (banda Ku) e receptor compatível, sem perda de canais.','["Famílias inscritas no CadÚnico","Renda por pessoa até meio salário mínimo","Ter parabólica tradicional em casa","Residir em região elegível pelo cronograma"]'::jsonb,'["Kit gratuito"]'::jsonb,'[{"titulo":"Ligue 0800 729 2404","descricao":"Central oficial do Siga Antenado."},{"titulo":"Confirme o agendamento","descricao":"Equipe credenciada combina dia da instalação."},{"titulo":"Receba antena e receptor","descricao":"Instalação é gratuita."},{"titulo":"Sintonize os canais","descricao":"Equipe deixa funcionando antes de sair."}]'::jsonb,'["CPF","NIS / CadÚnico atualizado","Comprovante de residência","Documento de identidade"]'::jsonb,'{"dicas":["Confirme sempre a identidade do técnico","Guarde o protocolo do pedido","Pergunte sobre canais regionais"],"errosComuns":[{"titulo":"Pagar por instalação","descricao":"É 100% gratuito; cuidado com golpes."},{"titulo":"Recusar visita técnica","descricao":"Sem visita, não é possível instalar."},{"titulo":"Mudar dados sem avisar","descricao":"Telefone errado impede o agendamento."}],"faq":[{"pergunta":"Vou perder canais?","resposta":"Não, os mesmos canais continuam, em alta definição."},{"pergunta":"Tem custo de manutenção?","resposta":"Não, mas você cuida do equipamento depois da entrega."},{"pergunta":"Posso pedir mesmo morando em apartamento?","resposta":"Sim, desde que haja autorização do condomínio."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('telefone-popular','Telefone Popular','Linha de telefone fixo com tarifa reduzida para o CadÚnico.',(SELECT id FROM public.categories WHERE slug='energia-agua-comunicacao'),'Zap','from-amber-500 to-orange-600',true,16) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='telefone-popular'),'O Telefone Popular (Acesso Individual Classe Especial - AICE) é uma linha telefônica fixa com mensalidade e tarifas reduzidas oferecida pelas operadoras a famílias inscritas no CadÚnico.','["Famílias inscritas no CadÚnico","Renda por pessoa até meio salário mínimo","Uma linha AICE por família","Apenas em endereços com viabilidade técnica"]'::jsonb,'["Mensalidade reduzida"]'::jsonb,'[{"titulo":"Procure operadoras do AICE","descricao":"Verifique quais oferecem na sua região (Oi, Vivo, etc.)."},{"titulo":"Apresente CPF e NIS","descricao":"A operadora consulta o CadÚnico."},{"titulo":"Agende a instalação","descricao":"Um técnico instala a linha em casa."},{"titulo":"Comece a usar","descricao":"Mensalidade reduzida aparece na primeira fatura."}]'::jsonb,'["CPF do responsável","NIS","Comprovante de residência","Documento de identidade"]'::jsonb,'{"dicas":["Compare custos com celular pré-pago","Atualize CadÚnico para manter o desconto","Use para chamadas locais principalmente"],"errosComuns":[{"titulo":"Já ter outra linha fixa no nome","descricao":"Só é permitida uma linha AICE por família."},{"titulo":"Esquecer de informar mudança","descricao":"Mudança de endereço pode exigir nova solicitação."},{"titulo":"Ultrapassar minutos","descricao":"Acima da franquia, tarifa volta ao normal."}],"faq":[{"pergunta":"Funciona em qualquer lugar?","resposta":"Só onde há rede da operadora compatível."},{"pergunta":"Inclui internet?","resposta":"Não, é apenas voz."},{"pergunta":"Posso usar para celular?","resposta":"Sim, mas o desconto é maior para chamadas locais fixas."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('internet-brasil','Programa Internet Brasil','Pacote de dados gratuito de internet para estudantes da rede pública.',(SELECT id FROM public.categories WHERE slug='energia-agua-comunicacao'),'Zap','from-amber-500 to-orange-600',true,17) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='internet-brasil'),'O Internet Brasil oferece chip ou pacote de dados gratuito para estudantes da rede pública de Ensino Médio em famílias inscritas no CadÚnico, garantindo acesso à internet para estudo.','["Estudantes da rede pública de Ensino Médio","Famílias inscritas no CadÚnico","Renda por pessoa até meio salário mínimo","Estar matriculado e frequente"]'::jsonb,'["Pacote de dados gratuito"]'::jsonb,'[{"titulo":"Confirme adesão da escola","descricao":"A escola precisa estar cadastrada no programa."},{"titulo":"Faça o cadastro indicado pela escola","descricao":"A escola repassa o link/formulário do MEC."},{"titulo":"Retire o chip","descricao":"Em postos credenciados ou na própria escola."},{"titulo":"Ative e use","descricao":"Coloque o chip no celular e use para estudar."}]'::jsonb,'["CPF do estudante e responsável","Matrícula em escola pública","NIS / CadÚnico atualizado","Endereço residencial"]'::jsonb,'{"dicas":["Priorize plataformas educacionais","Cuide do aparelho onde está o chip","Verifique a velocidade no app da operadora"],"errosComuns":[{"titulo":"Achar que serve para qualquer coisa","descricao":"O foco é uso educacional."},{"titulo":"Não retirar o chip no prazo","descricao":"Perde a vaga."},{"titulo":"Mudar de escola sem avisar","descricao":"Pode interromper o pacote."}],"faq":[{"pergunta":"Tem custo?","resposta":"Não. Pacote e chip são gratuitos."},{"pergunta":"Posso usar para redes sociais?","resposta":"Sim, mas o consumo entra na franquia."},{"pergunta":"Funciona em qualquer celular?","resposta":"Sim, em aparelhos desbloqueados que aceitem o chip."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('minha-casa-minha-vida','Minha Casa Minha Vida','Casa própria com subsídio do governo e juros baixos.',(SELECT id FROM public.categories WHERE slug='habitacao'),'Home','from-emerald-500 to-teal-600',true,18) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='minha-casa-minha-vida'),'O Minha Casa Minha Vida é o programa habitacional do Governo Federal que oferece subsídios, juros reduzidos e parcelas acessíveis para a aquisição da casa própria, com faixas que atendem desde famílias de baixíssima renda até a classe média.','["Faixa Urbana 1: renda até R$ 2.640","Faixa Urbana 2: renda até R$ 4.400","Faixa Urbana 3: renda até R$ 8.000","Famílias rurais conforme faixa específica","Não possuir imóvel residencial no Brasil"]'::jsonb,'["Subsídios e juros reduzidos"]'::jsonb,'[{"titulo":"Faixa 1: vá à prefeitura","descricao":"Cadastre-se no programa habitacional do município."},{"titulo":"Faixa 2 e 3: vá à Caixa","descricao":"Procure agência da Caixa ou correspondente."},{"titulo":"Simule o financiamento","descricao":"Use o simulador no app/site da Caixa."},{"titulo":"Escolha o imóvel e assine","descricao":"Documente compra, assine contrato e mude para sua casa."}]'::jsonb,'["CPF e RG","Comprovante de renda","Certidão de estado civil","Comprovante de residência","Inscrição em programa habitacional municipal (Faixa 1)"]'::jsonb,'{"dicas":["Junte uma entrada para reduzir parcelas","Use FGTS como parte do pagamento","Confira a documentação do imóvel antes de assinar"],"errosComuns":[{"titulo":"Achar que basta se inscrever","descricao":"A seleção depende de critérios e disponibilidade."},{"titulo":"Ter outro imóvel em nome","descricao":"Reprova automaticamente o financiamento."},{"titulo":"Não regularizar nome no SPC/Serasa","descricao":"Restrições impedem o crédito."}],"faq":[{"pergunta":"Posso usar FGTS?","resposta":"Sim, como entrada e amortização."},{"pergunta":"Casais precisam comprar juntos?","resposta":"Não necessariamente, mas renda pode ser combinada."},{"pergunta":"Tem programa rural?","resposta":"Sim, com regras específicas via INCRA e bancos."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('reforma-agraria','Programa Nacional de Reforma Agrária','Acesso à terra para trabalhadores rurais sem terra.',(SELECT id FROM public.categories WHERE slug='habitacao'),'Home','from-emerald-500 to-teal-600',true,19) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='reforma-agraria'),'O Programa Nacional de Reforma Agrária, conduzido pelo INCRA, busca democratizar o acesso à terra, assentando trabalhadores rurais sem terra em áreas obtidas por desapropriação, compra ou doação, com apoio à produção e moradia.','["Trabalhadores rurais sem terra","Pequenos agricultores com pouca terra","Posseiros, arrendatários e parceiros","Famílias em situação de vulnerabilidade rural"]'::jsonb,'["Lote de terra + apoio"]'::jsonb,'[{"titulo":"Cadastre-se no Sipra/INCRA","descricao":"Procure a superintendência regional do INCRA."},{"titulo":"Participe de associações","descricao":"Movimentos sociais ajudam no acompanhamento."},{"titulo":"Aguarde a chamada","descricao":"INCRA convoca conforme abertura de novos assentamentos."},{"titulo":"Receba o lote","descricao":"Após seleção, há posse provisória e depois definitiva."}]'::jsonb,'["CPF e identidade","Comprovante de atividade rural","Declaração de não possuir terra","Documentos do núcleo familiar"]'::jsonb,'{"dicas":["Procure sindicato rural local","Mantenha contato com a superintendência","Participe das reuniões dos assentados"],"errosComuns":[{"titulo":"Achar que é rápido","descricao":"O processo costuma levar anos."},{"titulo":"Não cadastrar família toda","descricao":"Compromete a análise."},{"titulo":"Vender o lote irregularmente","descricao":"Pode perder a terra."}],"faq":[{"pergunta":"Quem mora na cidade pode?","resposta":"Em regra exige histórico/perfil de trabalho rural."},{"pergunta":"Posso receber o título definitivo?","resposta":"Sim, após cumpridas as exigências do INCRA."},{"pergunta":"Tem crédito junto?","resposta":"Sim, créditos de instalação (programa específico)."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('creditos-instalacao','Créditos de Instalação da Reforma Agrária','Recursos para assentados começarem a produzir e morar no lote.',(SELECT id FROM public.categories WHERE slug='habitacao'),'Home','from-emerald-500 to-teal-600',true,20) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='creditos-instalacao'),'Os Créditos de Instalação são valores oferecidos pelo INCRA a famílias recém-assentadas para apoio à instalação, fomento à produção, recuperação de áreas degradadas, semiárido e construção/reforma da moradia no lote.','["Famílias assentadas pelo INCRA","Estar com cadastro Sipra ativo","Não ter recebido a modalidade anteriormente","Cumprir contrapartidas de produção"]'::jsonb,'["Até R$ 31 mil em modalidades"]'::jsonb,'[{"titulo":"Procure o INCRA","descricao":"Solicite junto à superintendência regional ou unidade avançada."},{"titulo":"Apresente plano de uso","descricao":"Detalhe como vai aplicar o recurso."},{"titulo":"Acompanhe a liberação","descricao":"Pagamento sai via Caixa em parcelas conforme modalidade."},{"titulo":"Preste contas","descricao":"Comprove a aplicação para liberar próximas parcelas."}]'::jsonb,'["CPF e identidade","Contrato de concessão de uso (CCU)","Plano de aplicação do recurso","Comprovantes de residência no lote"]'::jsonb,'{"dicas":["Junte notas fiscais de tudo que comprar","Combine com Pronaf para potencializar","Peça apoio técnico ao INCRA"],"errosComuns":[{"titulo":"Aplicar fora do plano","descricao":"Pode bloquear novas modalidades."},{"titulo":"Não prestar contas","descricao":"Impede liberação seguinte."},{"titulo":"Repassar o recurso a terceiros","descricao":"Configura irregularidade."}],"faq":[{"pergunta":"Posso usar para casa?","resposta":"Sim, na modalidade ''Habitação'' ou similar."},{"pergunta":"Pode ser dividido entre famílias?","resposta":"Em geral o crédito é por família assentada."},{"pergunta":"Quanto tempo até receber?","resposta":"Varia conforme orçamento e cronograma do INCRA."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('terra-brasil','Terra Brasil (Crédito Fundiário)','Financiamento para comprar terra e ter sua propriedade rural.',(SELECT id FROM public.categories WHERE slug='habitacao'),'Home','from-emerald-500 to-teal-600',true,21) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='terra-brasil'),'O Terra Brasil (antigo Programa Nacional de Crédito Fundiário) financia a aquisição de imóveis rurais e investimentos básicos para agricultores familiares, jovens rurais e trabalhadores sem terra, com prazos longos e juros baixos.','["Agricultores familiares com DAP/CAF","Jovens rurais com idade conforme edital","Trabalhadores rurais sem terra","Renda anual familiar dentro do limite do programa"]'::jsonb,'["Financiamento de longo prazo"]'::jsonb,'[{"titulo":"Procure o sindicato rural ou EMATER","descricao":"Eles ajudam a montar o projeto."},{"titulo":"Identifique o imóvel","descricao":"Negocie com vendedor e providencie documentos."},{"titulo":"Apresente o projeto ao agente financeiro","descricao":"Banco do Brasil, Banco do Nordeste, etc."},{"titulo":"Aguarde aprovação","descricao":"Assinado o contrato, terra passa para o agricultor."}]'::jsonb,'["DAP ou CAF do agricultor familiar","CPF e identidade","Comprovante de atividade rural","Projeto técnico simplificado"]'::jsonb,'{"dicas":["Negocie com vendedor a documentação em dia","Conheça o imóvel antes de fechar","Considere acesso à água e estradas"],"errosComuns":[{"titulo":"Comprar terra sem regularização","descricao":"Documentação irregular barra o financiamento."},{"titulo":"Projeto sem viabilidade","descricao":"Banco recusa quando não fecha as contas."},{"titulo":"Não acompanhar o processo","descricao":"Atrasos podem cancelar a proposta."}],"faq":[{"pergunta":"Posso comprar com outra família?","resposta":"Sim, em modalidades coletivas/grupais."},{"pergunta":"Tem carência?","resposta":"Sim, costuma haver carência para começar a pagar."},{"pergunta":"Pode usar para reforma da casa?","resposta":"Sim, dentro dos investimentos básicos."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('urbanizacao-assentamentos','Urbanização de Assentamentos Precários','Obras de infraestrutura, moradia e regularização em comunidades.',(SELECT id FROM public.categories WHERE slug='habitacao'),'Home','from-emerald-500 to-teal-600',true,22) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='urbanizacao-assentamentos'),'O Programa de Urbanização de Assentamentos Precários executa obras de infraestrutura (água, esgoto, ruas), construção e melhoria de moradias e regularização fundiária em favelas, palafitas e ocupações irregulares.','["Moradores de assentamentos precários selecionados","Famílias de baixa renda que vivam na área","Comunidades incluídas em plano municipal","Famílias afetadas por risco ambiental"]'::jsonb,'["Obras e regularização"]'::jsonb,'[{"titulo":"Procure a Secretaria de Habitação","descricao":"Cada município gerencia o programa localmente."},{"titulo":"Participe das reuniões comunitárias","descricao":"Plano de urbanização é decidido junto à comunidade."},{"titulo":"Cadastre a família","descricao":"Inclua todos os moradores."},{"titulo":"Acompanhe as obras","descricao":"Fiscalize prazos, qualidade e remoções."}]'::jsonb,'["CPF e identidade","Comprovante de moradia na área","Inscrição em cadastro habitacional municipal","Documentos pedidos no projeto local"]'::jsonb,'{"dicas":["Forme associação de moradores","Acompanhe as licitações","Cobre regularização do título"],"errosComuns":[{"titulo":"Não participar do cadastro","descricao":"Quem não cadastra pode ficar de fora."},{"titulo":"Vender a casa pré-melhoria","descricao":"Pode perder direitos."},{"titulo":"Ignorar reassentamentos","descricao":"Áreas de risco precisam ser deixadas."}],"faq":[{"pergunta":"Vou ter que sair de casa?","resposta":"Em áreas de risco, sim; com solução habitacional definitiva."},{"pergunta":"Custa alguma coisa?","resposta":"As obras são públicas; podem existir contrapartidas mínimas."},{"pergunta":"E a escritura?","resposta":"A regularização fundiária faz parte do programa."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('dom-helder-camara','Projeto Dom Hélder Câmara','Apoio a famílias da reforma agrária do Semiárido.',(SELECT id FROM public.categories WHERE slug='habitacao'),'Home','from-emerald-500 to-teal-600',true,23) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='dom-helder-camara'),'O Projeto Dom Hélder Câmara, conduzido pelo MDA/INCRA com apoio internacional, oferece assistência técnica, capacitação, infraestrutura hídrica e apoio a iniciativas produtivas para famílias assentadas e agricultores familiares do Semiárido brasileiro.','["Famílias assentadas da reforma agrária no Semiárido","Agricultores familiares pobres da região","Mulheres rurais e jovens rurais","Comunidades tradicionais selecionadas"]'::jsonb,'["Assistência técnica e recursos"]'::jsonb,'[{"titulo":"Procure a Ater do projeto","descricao":"Equipes técnicas atuam em territórios definidos."},{"titulo":"Participe das atividades","descricao":"Capacitações, mutirões e feiras."},{"titulo":"Apresente projeto produtivo","descricao":"Com apoio da equipe técnica."},{"titulo":"Receba acompanhamento","descricao":"Técnicos visitam a propriedade regularmente."}]'::jsonb,'["CPF e identidade","DAP/CAF de agricultor familiar","Comprovação de residência rural","Documentos pedidos pela coordenação local"]'::jsonb,'{"dicas":["Organize-se em associação ou cooperativa","Use o que aprende nos cursos","Aposte na convivência com o Semiárido"],"errosComuns":[{"titulo":"Esperar ''cesta básica''","descricao":"O projeto foca em produção e renda, não em doação."},{"titulo":"Não participar das atividades","descricao":"Faltas constantes podem desligar da equipe."},{"titulo":"Falta de organização coletiva","descricao":"Muitos benefícios passam por associações/cooperativas."}],"faq":[{"pergunta":"Vale para todo o Nordeste?","resposta":"Foca em territórios do Semiárido, em vários estados."},{"pergunta":"Tem dinheiro direto?","resposta":"Em geral é assistência e investimento estruturante."},{"pergunta":"Junto com Bolsa Família?","resposta":"Sim, são programas independentes."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('paa','Programa de Aquisição de Alimentos (PAA)','Governo compra alimentos da agricultura familiar e doa para quem precisa.',(SELECT id FROM public.categories WHERE slug='agricultura'),'Sprout','from-lime-500 to-green-600',true,24) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='paa'),'O PAA compra alimentos produzidos por agricultores familiares e os destina a pessoas em situação de insegurança alimentar, escolas, hospitais e equipamentos públicos, gerando renda no campo e combatendo a fome.','["Agricultores familiares com DAP/CAF ativa","Cooperativas e associações da agricultura familiar","Comunidades quilombolas, indígenas e tradicionais","Pescadores artesanais"]'::jsonb,'["Compra com preço justo"]'::jsonb,'[{"titulo":"Procure a Conab ou prefeitura","descricao":"Verifique editais abertos no município."},{"titulo":"Adira por uma organização","descricao":"Cooperativa/associação facilita a venda coletiva."},{"titulo":"Entregue a produção","descricao":"Cumprindo cronograma e padrão de qualidade."},{"titulo":"Receba o pagamento","descricao":"Direto na conta após validação."}]'::jsonb,'["DAP ou CAF","CPF e identidade","Comprovante de produção","Conta bancária para recebimento"]'::jsonb,'{"dicas":["Planeje a produção pelo calendário de entrega","Junte-se a outras famílias para vender mais","Use a renda também para investir na propriedade"],"errosComuns":[{"titulo":"DAP/CAF desatualizada","descricao":"Bloqueia automaticamente a participação."},{"titulo":"Entregar fora do padrão","descricao":"Cargas recusadas geram prejuízo."},{"titulo":"Vender por fora","descricao":"Quebra do contrato compromete novas chamadas."}],"faq":[{"pergunta":"Tem limite por família?","resposta":"Sim, definido a cada edital."},{"pergunta":"Posso doar diretamente?","resposta":"O PAA já direciona para entidades; o agricultor vende."},{"pergunta":"Vale para hortaliças?","resposta":"Sim, hortaliças, frutas, grãos, mel, etc."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('fomento-rural','Programa de Fomento às Atividades Produtivas Rurais','Recurso não reembolsável para famílias pobres começarem a produzir.',(SELECT id FROM public.categories WHERE slug='agricultura'),'Sprout','from-lime-500 to-green-600',true,25) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='fomento-rural'),'O Fomento Rural concede recurso não reembolsável e assistência técnica a famílias rurais em situação de pobreza inscritas no CadÚnico, para implantar pequenos projetos produtivos (horta, criação, beneficiamento).','["Famílias rurais inscritas no CadÚnico","Renda familiar dentro do limite do programa","Agricultores familiares com DAP/CAF","Comunidades tradicionais e assentados"]'::jsonb,'["Até R$ 6 mil por família"]'::jsonb,'[{"titulo":"Procure a ATER","descricao":"Empresa de Assistência Técnica e Extensão Rural credenciada."},{"titulo":"Construa o projeto","descricao":"Junto com técnico, monte um projeto adequado à propriedade."},{"titulo":"Inscreva no SIG-Fomento","descricao":"O técnico cadastra a família no sistema."},{"titulo":"Receba as parcelas","descricao":"Pagamento ocorre via Caixa em até duas parcelas."}]'::jsonb,'["CPF e identidade","DAP/CAF se houver","CadÚnico atualizado","Comprovante de residência rural"]'::jsonb,'{"dicas":["Cuide bem dos animais/plantas recebidos","Use a ATER para crescer aos poucos","Combine com outros programas (PAA, PNAE)"],"errosComuns":[{"titulo":"Aplicar fora do projeto","descricao":"Pode obrigar devolução do recurso."},{"titulo":"Esperar dinheiro sem técnico","descricao":"Sem ATER não há projeto aprovado."},{"titulo":"Vender o que recebeu","descricao":"Equipamentos comprados são para a família."}],"faq":[{"pergunta":"Preciso devolver?","resposta":"Não, é recurso não reembolsável."},{"pergunta":"Posso pedir várias vezes?","resposta":"Em regra, uma vez por família, salvo programas específicos."},{"pergunta":"Posso usar para comprar terra?","resposta":"Não. Para terra, use o Terra Brasil."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('cisternas','Programa Cisternas','Cisternas e tecnologias de água para o Semiárido.',(SELECT id FROM public.categories WHERE slug='agricultura'),'Sprout','from-lime-500 to-green-600',true,26) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='cisternas'),'O Programa Cisternas instala cisternas de placas (consumo humano) e cisternas para produção (P1+2) em áreas rurais do Semiárido, garantindo segurança hídrica e melhorando a vida das famílias.','["Famílias rurais do Semiárido sem acesso adequado à água","Inscrição no CadÚnico","Critérios das entidades executoras (Asa Brasil, etc.)","Comunidades tradicionais e assentamentos"]'::jsonb,'["Cisterna instalada"]'::jsonb,'[{"titulo":"Procure entidades parceiras","descricao":"Diocese, ONGs e prefeituras conveniadas."},{"titulo":"Cadastre a família","descricao":"Visita social verifica o perfil."},{"titulo":"Aguarde a obra","descricao":"Pedreiros locais constroem a cisterna."},{"titulo":"Receba capacitação","descricao":"Use água com cuidado e mantenha a estrutura."}]'::jsonb,'["CPF e identidade","NIS / CadÚnico","Comprovante de residência rural","Indicação por entidade executora local"]'::jsonb,'{"dicas":["Mantenha a tampa sempre fechada","Cuide das calhas e telhado","Use a cisterna de produção para horta e animais"],"errosComuns":[{"titulo":"Usar a cisterna para outros fins","descricao":"Pode contaminar a água potável."},{"titulo":"Não fazer limpeza periódica","descricao":"Reduz a qualidade da água."},{"titulo":"Cadastros duplicados","descricao":"Bloqueiam a entrega."}],"faq":[{"pergunta":"Tem custo?","resposta":"Não, é gratuita para famílias selecionadas."},{"pergunta":"Posso pedir cisterna maior?","resposta":"Existem modelos de produção (P1+2 e enxurrada)."},{"pergunta":"Vale fora do Semiárido?","resposta":"O foco é o Semiárido, mas há ações em outras regiões."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('bolsa-verde','Bolsa Verde','Renda extra para famílias que protegem a floresta.',(SELECT id FROM public.categories WHERE slug='agricultura'),'Sprout','from-lime-500 to-green-600',true,27) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='bolsa-verde'),'O Bolsa Verde é um programa de apoio à conservação ambiental que paga um valor trimestral a famílias em extrema pobreza que vivem em áreas de uso sustentável (extrativistas, ribeirinhos, assentamentos ambientalmente diferenciados) e conservam o meio ambiente.','["Famílias em extrema pobreza inscritas no CadÚnico","Residir em áreas de uso sustentável previstas no programa","Cumprir o termo de adesão à conservação","Manter atividades compatíveis com a área"]'::jsonb,'["R$ 600 trimestrais (referência)"]'::jsonb,'[{"titulo":"Aguarde chamamento na área","descricao":"Programa atua em áreas selecionadas."},{"titulo":"Cadastre a família","descricao":"Equipe do ICMBio/INCRA/órgãos parceiros faz o cadastro."},{"titulo":"Assine o termo","descricao":"Comprometendo-se com a conservação."},{"titulo":"Receba parcelas","descricao":"Pagamento trimestral via Caixa."}]'::jsonb,'["CPF e identidade","NIS / CadÚnico atualizado","Comprovação de residência na área","Termo de adesão assinado"]'::jsonb,'{"dicas":["Combine com PAA e Pronaf","Mantenha registros de atividades sustentáveis","Participe das reuniões com órgãos ambientais"],"errosComuns":[{"titulo":"Desmatamento ou degradação","descricao":"Suspende ou cancela o benefício."},{"titulo":"Sair da área sem aviso","descricao":"Mudança de residência encerra o pagamento."},{"titulo":"CadÚnico vencido","descricao":"Bloqueia automaticamente."}],"faq":[{"pergunta":"Acumula com Bolsa Família?","resposta":"Sim, é programa complementar."},{"pergunta":"Vale para qualquer floresta?","resposta":"Não, apenas áreas previstas (Resex, PAE, etc.)."},{"pergunta":"Tem fiscalização?","resposta":"Sim, com uso de imagens de satélite e visitas."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('ada','Ação de Distribuição de Alimentos (ADA)','Cestas de alimentos para grupos em vulnerabilidade alimentar.',(SELECT id FROM public.categories WHERE slug='agricultura'),'Sprout','from-lime-500 to-green-600',true,28) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='ada'),'A Ação de Distribuição de Alimentos entrega cestas a grupos populacionais em insegurança alimentar e nutricional, como indígenas, quilombolas, comunidades atingidas por desastres e acampamentos de reforma agrária.','["Comunidades indígenas","Comunidades quilombolas","Acampamentos da reforma agrária","Famílias atingidas por desastres ou calamidades"]'::jsonb,'["Cesta de alimentos"]'::jsonb,'[{"titulo":"Articulação institucional","descricao":"A entrega é definida em parceria com órgãos públicos."},{"titulo":"Cadastro coletivo","descricao":"A liderança/órgão organiza a lista."},{"titulo":"Recebimento em pontos definidos","descricao":"Conab e parceiros entregam as cestas."},{"titulo":"Distribuição interna","descricao":"Comunidade distribui conforme acordado."}]'::jsonb,'["Identificação da comunidade","Lista de famílias atendidas","Encaminhamento de órgão público (Funai, INCRA, Defesa Civil, etc.)","Documentos individuais quando exigidos"]'::jsonb,'{"dicas":["Articule via cacique, líder quilombola ou comissão","Combine com agricultura própria","Procure também o PAA"],"errosComuns":[{"titulo":"Tentativa individual de cadastro","descricao":"A ação é coletiva via órgãos públicos."},{"titulo":"Dupla contagem de famílias","descricao":"Distorce a distribuição."},{"titulo":"Vender as cestas","descricao":"Configura desvio de finalidade."}],"faq":[{"pergunta":"Qualquer um pode pedir?","resposta":"Não, atende públicos específicos com vulnerabilidade alimentar."},{"pergunta":"Tem frequência fixa?","resposta":"Varia conforme contexto e disponibilidade."},{"pergunta":"É a mesma coisa que cesta básica?","resposta":"Não, é uma ação federal específica."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('farmacia-popular','Farmácia Popular','Remédios de uso contínuo gratuitos ou com grande desconto.',(SELECT id FROM public.categories WHERE slug='saude-inclusao'),'HeartPulse','from-red-500 to-pink-600',true,29) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='farmacia-popular'),'O Farmácia Popular oferece medicamentos para doenças crônicas (hipertensão, diabetes, asma, etc.), anticoncepcionais e fraldas geriátricas, de forma gratuita ou com desconto de até 90%, em farmácias credenciadas em todo o Brasil.','["Qualquer pessoa com CPF e receita médica válida","Gratuidade total para medicamentos de hipertensão, diabetes e asma","Beneficiários do Bolsa Família com gratuidade ampliada","Uso conforme a receita"]'::jsonb,'["Gratuito ou até 90% off"]'::jsonb,'[{"titulo":"Tenha a receita médica","descricao":"Pública ou particular, dentro da validade."},{"titulo":"Procure farmácia credenciada","descricao":"Consulte a lista no site do Ministério da Saúde."},{"titulo":"Apresente CPF e receita","descricao":"O sistema verifica o programa."},{"titulo":"Retire o medicamento","descricao":"Gratuito ou com desconto, conforme o caso."}]'::jsonb,'["CPF","Receita médica válida","Documento de identidade","Cartão do SUS (opcional)"]'::jsonb,'{"dicas":["Peça receita em letra legível ou impressa","Tire foto da receita para guardar","Confira validade do medicamento ao retirar"],"errosComuns":[{"titulo":"Receita vencida","descricao":"Receita para crônico costuma valer 6 meses; confira."},{"titulo":"Comprar fora do credenciado","descricao":"Sem o desconto do programa."},{"titulo":"Misturar CPFs","descricao":"Sempre use o CPF do paciente."}],"faq":[{"pergunta":"Funciona em rede privada?","resposta":"Sim, em farmácias credenciadas como Drogasil, Pague Menos, etc."},{"pergunta":"Posso pegar para outra pessoa?","resposta":"Sim, com receita em nome dela e CPF dela."},{"pergunta":"Tem fraldas?","resposta":"Sim, para idosos com prescrição."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('carteira-idoso','Carteira da Pessoa Idosa','Transporte interestadual gratuito ou com 50% off para idosos.',(SELECT id FROM public.categories WHERE slug='saude-inclusao'),'HeartPulse','from-red-500 to-pink-600',true,30) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='carteira-idoso'),'A Carteira da Pessoa Idosa garante a idosos com 60 anos ou mais e renda de até 2 salários mínimos duas vagas gratuitas por viagem em ônibus, trens e barcos interestaduais, ou 50% de desconto se as vagas gratuitas já estiverem ocupadas.','["Pessoas com 60 anos ou mais","Renda mensal de até 2 salários mínimos","Inscrição no CadÚnico ou comprovação direta de renda","Viagens interestaduais regulares"]'::jsonb,'["Gratuidade ou 50% off"]'::jsonb,'[{"titulo":"Procure o CRAS","descricao":"Solicite a Carteira da Pessoa Idosa."},{"titulo":"Apresente os documentos","descricao":"Inclui foto e comprovante de renda."},{"titulo":"Receba a carteira","descricao":"Pode ser impressa ou digital."},{"titulo":"Use ao comprar passagem","descricao":"Procure a empresa com antecedência mínima."}]'::jsonb,'["CPF e identidade com foto","Comprovante de renda (ou NIS)","Foto recente 3x4","Comprovante de residência"]'::jsonb,'{"dicas":["Reserve a passagem com antecedência","Tenha sempre a carteira em mãos","Se a empresa negar, registre denúncia na ANTT"],"errosComuns":[{"titulo":"Comprar passagem em cima da hora","descricao":"As vagas gratuitas exigem antecedência (em geral 3h antes)."},{"titulo":"Confundir com transporte municipal","descricao":"O municipal é regulado pela cidade."},{"titulo":"Renda acima do limite","descricao":"Quem ganha mais de 2 SM perde esse direito."}],"faq":[{"pergunta":"Vale para avião?","resposta":"Não, é para terrestre, ferroviário e aquaviário interestadual."},{"pergunta":"Funciona para acompanhante?","resposta":"Não automaticamente; depende de avaliação."},{"pergunta":"Vale dentro da mesma cidade?","resposta":"Não, transporte urbano é regra municipal."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('passe-livre-pcd','Passe Livre para Pessoas com Deficiência','Transporte interestadual gratuito para PcD de baixa renda.',(SELECT id FROM public.categories WHERE slug='saude-inclusao'),'HeartPulse','from-red-500 to-pink-600',true,31) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='passe-livre-pcd'),'O Passe Livre é um benefício federal que garante gratuidade total em ônibus, trens e barcos interestaduais a pessoas com deficiência comprovadamente carentes (renda familiar por pessoa de até 1 salário mínimo).','["Pessoas com deficiência (físico, mental, auditiva, visual, múltipla)","Renda familiar por pessoa de até 1 salário mínimo","Brasileiros e estrangeiros residentes","Possuir laudo médico oficial"]'::jsonb,'["Gratuito"]'::jsonb,'[{"titulo":"Acesse o site do Ministério dos Transportes","descricao":"Procure ''Passe Livre PcD''."},{"titulo":"Baixe formulários médicos","descricao":"Atestado Médico e Relatório Médico (RMA)."},{"titulo":"Envie a documentação","descricao":"Pelo correio para o endereço informado, sem custo."},{"titulo":"Aguarde a carteira","descricao":"Recebe pelo correio em casa."}]'::jsonb,'["CPF e identidade","Comprovante de renda familiar","Laudos médicos (Atestado e RMA)","Foto recente 3x4","Comprovante de residência"]'::jsonb,'{"dicas":["Procure ajuda no CRAS ou OAB se tiver dificuldades","Confirme antecedência de embarque com empresa","Carteira tem validade; renove antes de vencer"],"errosComuns":[{"titulo":"Laudo incompleto","descricao":"Médico precisa preencher tudo, com CID."},{"titulo":"Confundir com passe escolar","descricao":"São programas diferentes."},{"titulo":"Renda acima do limite","descricao":"Reprova o pedido."}],"faq":[{"pergunta":"Acompanhante viaja de graça?","resposta":"Em casos previstos, sim, com avaliação específica."},{"pergunta":"Posso usar para qualquer viagem?","resposta":"Sim, interestadual, em empresas autorizadas."},{"pergunta":"Vale para o municipal?","resposta":"Não, é regulamentado por leis locais."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('bpc-na-escola','BPC na Escola','Garante acesso à escola para crianças e jovens com deficiência que recebem BPC.',(SELECT id FROM public.categories WHERE slug='saude-inclusao'),'HeartPulse','from-red-500 to-pink-600',true,32) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='bpc-na-escola'),'O Programa BPC na Escola identifica barreiras e garante o acesso e a permanência na escola de crianças e adolescentes de 0 a 18 anos com deficiência beneficiárias do BPC, por meio de ação intersetorial entre assistência social, educação, saúde e direitos humanos.','["Crianças e adolescentes com deficiência de 0 a 18 anos","Recebedores do BPC","Família inscrita no CadÚnico","Residência em municípios aderidos"]'::jsonb,'["Acompanhamento educacional"]'::jsonb,'[{"titulo":"Confirme a adesão do município","descricao":"Procure a Assistência Social local."},{"titulo":"Receba a visita domiciliar","descricao":"Equipe aplica o questionário sobre barreiras de acesso."},{"titulo":"Acompanhamento intersetorial","descricao":"Educação, saúde e assistência atuam juntas."},{"titulo":"Matrícula e suporte na escola","descricao":"Família é apoiada para garantir estudo."}]'::jsonb,'["CPF e identidade da criança/adolescente","Documento do responsável","Concessão do BPC","Comprovante de matrícula ou interesse em estudar"]'::jsonb,'{"dicas":["Aceite a visita do agente","Comunique mudanças à escola","Procure CMEs ou Conselho Tutelar se houver barreiras"],"errosComuns":[{"titulo":"Não atender a visita","descricao":"Sem questionário, a família sai do programa."},{"titulo":"Cadastro desatualizado","descricao":"Compromete o acompanhamento."},{"titulo":"Acreditar que substitui a escola","descricao":"É apoio para o acesso e permanência."}],"faq":[{"pergunta":"Perde o BPC se entrar?","resposta":"Não, são complementares."},{"pergunta":"Funciona em todo Brasil?","resposta":"Apenas em municípios que aderiram."},{"pergunta":"E após os 18 anos?","resposta":"Outras políticas de inclusão e revisão do BPC se aplicam."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('scfv','Serviço de Convivência e Fortalecimento de Vínculos (SCFV)','Atividades em grupo para crianças, jovens e idosos via CRAS.',(SELECT id FROM public.categories WHERE slug='saude-inclusao'),'HeartPulse','from-red-500 to-pink-600',true,33) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='scfv'),'O SCFV oferece atividades em grupo, organizadas por faixa etária, em CRAS e centros conveniados, com foco em ampliar relações sociais e prevenir situações de risco — para crianças, adolescentes, jovens, adultos e idosos.','["Crianças de até 6 anos","Crianças e adolescentes de 6 a 17 anos","Jovens de 18 a 29 anos em vulnerabilidade","Pessoas idosas"]'::jsonb,'["Gratuito"]'::jsonb,'[{"titulo":"Procure o CRAS","descricao":"Pergunte pelos grupos disponíveis na unidade."},{"titulo":"Faça a inscrição","descricao":"A equipe avalia e indica o grupo adequado."},{"titulo":"Participe das atividades","descricao":"Encontros semanais ou quinzenais."},{"titulo":"Acompanhe outros encaminhamentos","descricao":"Saúde, educação e cultura podem ser articulados."}]'::jsonb,'["CPF e identidade","Comprovante de residência","Inscrição/atualização no CadÚnico (recomendada)","Encaminhamento do CRAS quando houver"]'::jsonb,'{"dicas":["Participe ativamente das oficinas","Convide vizinhos e familiares","Combine com Bolsa Família e BPC"],"errosComuns":[{"titulo":"Pensar que é só para crianças","descricao":"Há grupos para todas as idades."},{"titulo":"Faltar com frequência","descricao":"Pode ser desligado do grupo."},{"titulo":"Não levar a sério","descricao":"É uma política de proteção social."}],"faq":[{"pergunta":"Tem custo?","resposta":"Não, é gratuito."},{"pergunta":"Substitui escola?","resposta":"Não, complementa."},{"pergunta":"Funciona em todo município?","resposta":"Sim, todo CRAS deve ofertar SCFV."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('isencao-taxas-uniao','Isenção de Taxas sobre Imóveis da União','Isenção de foro e laudêmio em imóveis da União para baixa renda.',(SELECT id FROM public.categories WHERE slug='isencoes'),'BadgePercent','from-cyan-500 to-blue-600',true,34) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='isencao-taxas-uniao'),'A SPU concede isenção de pagamento de foro e laudêmio para ocupantes ou aforados de imóveis da União que comprovem ser de baixa renda, inscritos no CadÚnico ou em programas habitacionais sociais.','["Ocupantes ou aforados de imóveis da União","Renda familiar por pessoa até meio salário mínimo","Inscrição no CadÚnico","Imóvel utilizado como residência"]'::jsonb,'["Isenção total"]'::jsonb,'[{"titulo":"Acesse o portal da SPU","descricao":"Use o sistema SPUNet."},{"titulo":"Solicite o benefício","descricao":"Selecione ''Isenção de receitas patrimoniais''."},{"titulo":"Anexe documentos","descricao":"Comprove renda e residência."},{"titulo":"Aguarde análise","descricao":"Resultado sai pelo próprio sistema."}]'::jsonb,'["CPF e identidade","NIS / CadÚnico","Comprovante de ocupação do imóvel","Documentação do imóvel (RIP/CAT)"]'::jsonb,'{"dicas":["Atualize sempre o CadÚnico","Guarde o número do RIP do imóvel","Acompanhe o processo no SPUNet"],"errosComuns":[{"titulo":"Achar que isenção é automática","descricao":"É preciso solicitar formalmente."},{"titulo":"Renda acima do limite","descricao":"Pedido será negado."},{"titulo":"Documentação incompleta","descricao":"Atrasos comuns."}],"faq":[{"pergunta":"Vale para terrenos de marinha?","resposta":"Sim, é o caso clássico."},{"pergunta":"Acumula com Tarifa Social?","resposta":"Sim, são benefícios diferentes."},{"pergunta":"Quanto tempo dura a isenção?","resposta":"Enquanto persistirem as condições; precisa atualizar."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('descontos-inpi','Descontos nos Serviços do INPI','Até 60% de desconto para registrar marca, patente ou desenho no INPI.',(SELECT id FROM public.categories WHERE slug='isencoes'),'BadgePercent','from-cyan-500 to-blue-600',true,35) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='descontos-inpi'),'O INPI concede descontos de até 60% nas taxas de serviços (marcas, patentes, desenho industrial, software) para pessoas físicas, MEIs, ME, EPP, instituições de ensino, ICTs e cooperativas.','["Pessoas físicas","Microempreendedores Individuais (MEI)","Microempresas e Empresas de Pequeno Porte","Instituições de ensino e pesquisa","Cooperativas"]'::jsonb,'["Até 60% de desconto"]'::jsonb,'[{"titulo":"Cadastre-se no e-INPI","descricao":"Crie usuário no site do INPI."},{"titulo":"Gere a GRU correta","descricao":"Selecione o tipo de pessoa para aplicar o desconto."},{"titulo":"Pague a guia","descricao":"Com desconto aplicado."},{"titulo":"Acompanhe o pedido","descricao":"Use o e-INPI para responder exigências."}]'::jsonb,'["CPF ou CNPJ","Comprovação do enquadramento (MEI, ME, EPP)","Cadastro no e-INPI","Documentos do objeto a registrar (logo, descrição, etc.)"]'::jsonb,'{"dicas":["Faça busca prévia para evitar conflito de marca","Use serviços do Sebrae para apoio","Acompanhe pelo e-INPI semanalmente"],"errosComuns":[{"titulo":"Marcar tipo errado de pessoa","descricao":"Cobra o valor cheio."},{"titulo":"Não responder exigências","descricao":"Pode arquivar o pedido."},{"titulo":"Atrasar pagamento da GRU","descricao":"Suspende o processo."}],"faq":[{"pergunta":"Quanto custa registrar marca como MEI?","resposta":"Com desconto, costuma sair menos da metade do valor cheio."},{"pergunta":"Vale para software?","resposta":"Sim, registro de programa de computador."},{"pergunta":"Posso registrar marca pessoa física?","resposta":"Sim, desde que atue na atividade da marca."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('tarifa-social-cadunico','Integração Tarifa Social + CadÚnico','Como o CadÚnico libera vários benefícios de Tarifa Social automaticamente.',(SELECT id FROM public.categories WHERE slug='complementares'),'BookOpen','from-slate-600 to-slate-800',true,36) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='tarifa-social-cadunico'),'Com o CadÚnico atualizado, sua família pode receber automaticamente diversos benefícios: Tarifa Social de Energia, Auxílio Gás, Tarifa Social de Água, descontos em transporte e outros — sem precisar pedir um a um.','["Famílias inscritas no CadÚnico","Renda por pessoa até meio salário mínimo","CadÚnico atualizado nos últimos 24 meses","Cada benefício mantém suas regras específicas"]'::jsonb,'["Múltiplos descontos"]'::jsonb,'[{"titulo":"Vá ao CRAS","descricao":"Para cadastrar ou atualizar o CadÚnico."},{"titulo":"Leve documentos de todos da família","descricao":"Crianças, idosos, dependentes."},{"titulo":"Mantenha os dados em dia","descricao":"Atualize sempre que algo mudar."},{"titulo":"Use os benefícios conectados","descricao":"Confira em cada concessionária/órgão."}]'::jsonb,'["CPF do responsável","NIS de todos os membros","Documentos da família","Comprovante de residência"]'::jsonb,'{"dicas":["Foto do NIS sempre no celular","Lembre da data da última atualização","Procure CRAS a cada 2 anos no mínimo"],"errosComuns":[{"titulo":"Achar que pedido é um por um","descricao":"Vários se ativam automaticamente via CadÚnico."},{"titulo":"Esquecer atualização","descricao":"Bloqueia tudo de uma vez."},{"titulo":"Cadastrar só uma pessoa","descricao":"Toda a família precisa estar."}],"faq":[{"pergunta":"Onde vejo se meu CadÚnico está ok?","resposta":"No app ''Cadastro Único'' ou no CRAS."},{"pergunta":"Quem entra junto?","resposta":"Todos que moram na mesma residência."},{"pergunta":"Tem custo?","resposta":"Não, é gratuito sempre."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
INSERT INTO public.benefits(slug,name,short_description,category_id,icon,gradient,is_published,sort_order) VALUES ('acumulo-beneficios','Acúmulo Legal de Benefícios Sociais','Quais benefícios podem (e não podem) ser recebidos juntos.',(SELECT id FROM public.categories WHERE slug='complementares'),'BookOpen','from-slate-600 to-slate-800',true,37) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,short_description=EXCLUDED.short_description,category_id=EXCLUDED.category_id,icon=EXCLUDED.icon,gradient=EXCLUDED.gradient,is_published=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.benefit_contents(benefit_id,what_is,who_qualifies,value_info,how_to_apply,documents,important,is_restricted) VALUES ((SELECT id FROM public.benefits WHERE slug='acumulo-beneficios'),'Muitos benefícios sociais podem ser acumulados, desde que respeitadas regras específicas. Outros, como BPC e Bolsa Família para a mesma pessoa, têm restrições. Este guia ajuda a entender o que pode ser acumulado.','["Famílias dentro do perfil de cada benefício","CadÚnico atualizado","Documentação em dia","Cumprimento das regras de cada programa"]'::jsonb,'["Vários ao mesmo tempo"]'::jsonb,'[{"titulo":"Estude as regras de cada benefício","descricao":"Use guias oficiais e este catálogo."},{"titulo":"Cadastre-se no CadÚnico","descricao":"Base para a maioria dos programas."},{"titulo":"Solicite os benefícios compatíveis","descricao":"Bolsa Família, Auxílio Gás, Tarifa Social, etc."},{"titulo":"Acompanhe atualizações","descricao":"Regras mudam; fique atento."}]'::jsonb,'["CPF","NIS","Documentos solicitados em cada benefício","Comprovantes de renda"]'::jsonb,'{"dicas":["Bolsa Família + Auxílio Gás + Tarifa Social é combinação comum","Pé-de-Meia + Bolsa Família para famílias com estudante","BPC + Tarifa Social de Energia é permitido"],"errosComuns":[{"titulo":"Acumular BPC com Bolsa Família indevidamente","descricao":"Pode bloquear pagamento."},{"titulo":"Omitir renda","descricao":"Caracteriza fraude."},{"titulo":"Não atualizar mudanças","descricao":"Compromete todos os benefícios."}],"faq":[{"pergunta":"BPC + Bolsa Família?","resposta":"Não na mesma pessoa; podem coexistir na família em casos específicos."},{"pergunta":"BPC + Auxílio Gás?","resposta":"Sim, é uma combinação permitida."},{"pergunta":"Bolsa Família + seguro-desemprego?","resposta":"Pode, mas a renda pode mudar a faixa do Bolsa."}]}'::jsonb,true) ON CONFLICT(benefit_id) DO UPDATE SET what_is=EXCLUDED.what_is,who_qualifies=EXCLUDED.who_qualifies,value_info=EXCLUDED.value_info,how_to_apply=EXCLUDED.how_to_apply,documents=EXCLUDED.documents,important=EXCLUDED.important,is_restricted=EXCLUDED.is_restricted,updated_at=now();
